package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetBookReservationsUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase.ReserveBookCommand;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/books/{bookId}/reservations")
public class ReservationController {

    private final ReserveBookUseCase reserveBookUseCase;
    private final GetBookReservationsUseCase getBookReservationsUseCase;

    public ReservationController(ReserveBookUseCase reserveBookUseCase,
                                 GetBookReservationsUseCase getBookReservationsUseCase) {
        this.reserveBookUseCase = reserveBookUseCase;
        this.getBookReservationsUseCase = getBookReservationsUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ReservedPositionResponse reserveBook(@PathVariable UUID bookId, @RequestBody ReserveBookRequest request) {
        return ReservedPositionResponse.from(
                reserveBookUseCase.reserveBook(new ReserveBookCommand(bookId, request.memberId())));
    }

    @GetMapping
    public List<ReservationResponse> getReservations(@PathVariable UUID bookId) {
        return getBookReservationsUseCase.getBookReservations(bookId).stream()
                .map(ReservationResponse::from)
                .toList();
    }
}
