package com.example.lending.domain;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

// 한 책의 예약 줄. 소진된 예약도 함께 들고 있어 순번(sequence)이 겹치지 않게 한다.
// 줄에 서는 조건(책 상태)은 Book.reserveFor 가, 줄의 순서와 소진은 이 클래스가 맡는다.
public class ReservationQueue {

    private final UUID bookId;
    private final List<Reservation> reservations;

    private ReservationQueue(UUID bookId, List<Reservation> reservations) {
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        for (Reservation reservation : reservations) {
            if (!bookId.equals(reservation.getBookId())) {
                throw new IllegalArgumentException("reservation " + reservation.getId() + " is not for book " + bookId);
            }
        }
        this.reservations = new ArrayList<>(reservations);
        this.reservations.sort(Comparator.comparingLong(Reservation::getSequence));
    }

    public static ReservationQueue reconstitute(UUID bookId, List<Reservation> reservations) {
        return new ReservationQueue(bookId, reservations);
    }

    // 소진되지 않은 예약을 줄 선 순서대로 돌려준다. 맨 앞이 position 1 이다.
    public List<Reservation> waiting() {
        return reservations.stream().filter(r -> !r.isFulfilled()).toList();
    }

    public boolean isEmpty() {
        return waiting().isEmpty();
    }

    public int positionOf(UUID reservationId) {
        List<Reservation> waiting = waiting();
        for (int i = 0; i < waiting.size(); i++) {
            if (waiting.get(i).getId().equals(reservationId)) {
                return i + 1;
            }
        }
        throw new IllegalArgumentException("reservation is not waiting: " + reservationId);
    }

    // 저장할 때 쓰도록 소진된 예약까지 모두 돌려준다.
    public List<Reservation> all() {
        return List.copyOf(reservations);
    }

    Reservation enqueue(UUID memberId) {
        if (waiting().stream().anyMatch(r -> r.getMemberId().equals(memberId))) {
            throw new AlreadyReservedException(bookId, memberId);
        }
        long nextSequence = reservations.stream().mapToLong(Reservation::getSequence).max().orElse(0) + 1;
        Reservation reservation = Reservation.place(bookId, memberId, nextSequence);
        reservations.add(reservation);
        return reservation;
    }

    // 예약이 있으면 맨 앞 예약자만 빌릴 수 있다.
    void ensureMayBorrow(UUID memberId) {
        front().ifPresent(front -> {
            if (!front.getMemberId().equals(memberId)) {
                throw new ReservedForOtherException(bookId, memberId);
            }
        });
    }

    // 맨 앞 예약자가 빌리면 그 예약을 소진한다. 예약이 없으면 아무 일도 하지 않는다.
    void fulfillFor(UUID memberId) {
        ensureMayBorrow(memberId);
        front().ifPresent(Reservation::fulfill);
    }

    private Optional<Reservation> front() {
        return reservations.stream().filter(r -> !r.isFulfilled()).findFirst();
    }

    public UUID getBookId() {
        return bookId;
    }
}
