package com.example.lending.application.service;

import com.example.lending.application.port.in.GetBookReservationsUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadReservationPort;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Reservation;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;
import java.util.stream.IntStream;

@Service
@Transactional(readOnly = true)
public class GetBookReservationsService implements GetBookReservationsUseCase {

    private final LoadBookPort loadBookPort;
    private final LoadReservationPort loadReservationPort;

    public GetBookReservationsService(LoadBookPort loadBookPort, LoadReservationPort loadReservationPort) {
        this.loadBookPort = loadBookPort;
        this.loadReservationPort = loadReservationPort;
    }

    @Override
    public List<WaitingReservation> getBookReservations(UUID bookId) {
        if (loadBookPort.loadBook(bookId).isEmpty()) {
            throw new BookNotFoundException(bookId);
        }
        ReservationQueue queue = loadReservationPort.loadReservationQueue(bookId);
        List<Reservation> waiting = queue.waiting();
        return IntStream.range(0, waiting.size())
                .mapToObj(i -> new WaitingReservation(waiting.get(i).getId(), waiting.get(i).getMemberId(), i + 1))
                .toList();
    }
}
