package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadReservationPort;
import com.example.lending.application.port.out.SaveReservationPort;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Component;

import java.util.UUID;

@Component
public class ReservationPersistenceAdapter implements LoadReservationPort, SaveReservationPort {

    private final ReservationJpaRepository reservationJpaRepository;
    private final ReservationMapper reservationMapper = new ReservationMapper();

    public ReservationPersistenceAdapter(ReservationJpaRepository reservationJpaRepository) {
        this.reservationJpaRepository = reservationJpaRepository;
    }

    @Override
    public ReservationQueue loadReservationQueue(UUID bookId) {
        return ReservationQueue.reconstitute(bookId, reservationJpaRepository.findByBookIdOrderBySequenceAsc(bookId)
                .stream()
                .map(reservationMapper::toDomain)
                .toList());
    }

    @Override
    public void saveReservationQueue(ReservationQueue queue) {
        reservationJpaRepository.saveAll(queue.all().stream().map(reservationMapper::toEntity).toList());
    }
}
